# Enumerate cells where all four source junctions share the lattice-line color on demonstrations
for name,g,rr,cc,linecol in [('d1',D1,[0,21],[5,19],2),('d2',D2,rows2,cols2,5),('d3',D3,rows3,cols3,7)]:
    vals=[]
    for a,b in zip(rr,rr[1:]):
        for x,y in zip(cc,cc[1:]):
            corner=[g[a][x],g[a][y],g[b][x],g[b][y]]
            if all(v==linecol for v in corner): vals.append((a,x))
    print(name, vals)
